-- ============================================================================
-- E-commerce demo schema for text-to-SQL teaching.
-- 10 tables, ~20k rows each (generated by scripts/generate_data.py).
--
-- Two things here are deliberate teaching choices, not decoration:
--
--   1. COMMENT ON TABLE / COMMENT ON COLUMN everywhere.
--      Both LangChain (via our custom tools) and LlamaIndex (via context_str)
--      turn these comments into the "semantic layer" the LLM sees. A column
--      named `status` is ambiguous; a column with a comment saying
--      'order lifecycle state: placed | paid | shipped | delivered | cancelled'
--      is ground truth the model can use.
--
--   2. A dedicated read-only role (`text2sql_ro`).
--      The LLM is NEVER the security boundary. Prompts that say "do not run
--      DELETE" are a hint, not a control. The role below can only SELECT,
--      so even a successfully injected "DROP TABLE orders" fails at the
--      database. See the notebooks for the full discussion (and CVE-2024-23751
--      in LlamaIndex, which is exactly this failure mode).
--
-- Run order:  1) this file   2) scripts/generate_data.py
-- ============================================================================

SET client_min_messages = warning;

-- ---------------------------------------------------------------------------
-- Reference / dimension tables
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS categories (
    category_id   SERIAL PRIMARY KEY,
    name          VARCHAR(100) NOT NULL UNIQUE,
    description   TEXT,
    parent_id     INTEGER REFERENCES categories(category_id) ON DELETE SET NULL
);

COMMENT ON TABLE  categories IS 'Product taxonomy. Hierarchical: a category may have a parent category (e.g. "Laptops" under "Electronics").';
COMMENT ON COLUMN categories.category_id IS 'Primary key.';
COMMENT ON COLUMN categories.name IS 'Unique category name, e.g. "Electronics", "Kitchen".';
COMMENT ON COLUMN categories.parent_id IS 'Self-referencing FK to the parent category; NULL for top-level categories.';

CREATE TABLE IF NOT EXISTS suppliers (
    supplier_id   SERIAL PRIMARY KEY,
    name          VARCHAR(150) NOT NULL,
    contact_email VARCHAR(200),
    country       VARCHAR(60) NOT NULL,
    rating        NUMERIC(3, 2) CHECK (rating BETWEEN 0 AND 5)
);

COMMENT ON TABLE  suppliers IS 'Companies that supply products. rating is a quality score from 0.00 to 5.00 maintained by procurement.';
COMMENT ON COLUMN suppliers.rating IS 'Supplier quality score, 0.00 (worst) to 5.00 (best).';

CREATE TABLE IF NOT EXISTS products (
    product_id    SERIAL PRIMARY KEY,
    sku           VARCHAR(40) NOT NULL UNIQUE,
    name          VARCHAR(200) NOT NULL,
    category_id   INTEGER NOT NULL REFERENCES categories(category_id),
    supplier_id   INTEGER REFERENCES suppliers(supplier_id) ON DELETE SET NULL,
    unit_price    NUMERIC(10, 2) NOT NULL CHECK (unit_price >= 0),
    cost_price    NUMERIC(10, 2) NOT NULL CHECK (cost_price >= 0),
    stock_qty     INTEGER NOT NULL DEFAULT 0 CHECK (stock_qty >= 0),
    is_active     BOOLEAN NOT NULL DEFAULT TRUE,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE  products IS 'Sellable items. unit_price is what customers pay; cost_price is what we pay the supplier; margin = unit_price - cost_price.';
COMMENT ON COLUMN products.unit_price IS 'Customer-facing price per unit, in USD.';
COMMENT ON COLUMN products.cost_price IS 'Wholesale cost per unit, in USD. Used for profit calculations.';
COMMENT ON COLUMN products.stock_qty IS 'Current inventory on hand. Low stock = stock_qty < 20 (business rule).';
COMMENT ON COLUMN products.is_active IS 'FALSE means discontinued: never appears in new orders but historical rows remain.';

CREATE TABLE IF NOT EXISTS customers (
    customer_id   SERIAL PRIMARY KEY,
    first_name    VARCHAR(80) NOT NULL,
    last_name     VARCHAR(80) NOT NULL,
    email         VARCHAR(200) NOT NULL UNIQUE,
    phone         VARCHAR(30),
    country       VARCHAR(60) NOT NULL,
    date_of_birth DATE,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE  customers IS 'Registered customers. Full name = first_name || '' '' || last_name.';
COMMENT ON COLUMN customers.created_at IS 'Registration timestamp. "New customers in March 2024" means created_at in that month.';
COMMENT ON COLUMN customers.date_of_birth IS 'Used for age-segment questions (18th birthday is not until date_of_birth + 18 years).';

CREATE TABLE IF NOT EXISTS addresses (
    address_id    SERIAL PRIMARY KEY,
    customer_id   INTEGER NOT NULL REFERENCES customers(customer_id) ON DELETE CASCADE,
    line1         VARCHAR(200) NOT NULL,
    city          VARCHAR(100) NOT NULL,
    state         VARCHAR(100),
    postal_code   VARCHAR(20),
    country       VARCHAR(60) NOT NULL,
    is_default    BOOLEAN NOT NULL DEFAULT FALSE
);

COMMENT ON TABLE  addresses IS 'Customer shipping/billing addresses. One customer can have many addresses; is_default marks the primary one. Orders join to addresses, not directly to customers, for the shipping destination.';

-- ---------------------------------------------------------------------------
-- Fact tables
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS orders (
    order_id      SERIAL PRIMARY KEY,
    customer_id   INTEGER NOT NULL REFERENCES customers(customer_id),
    address_id    INTEGER NOT NULL REFERENCES addresses(address_id),
    status        VARCHAR(20) NOT NULL DEFAULT 'placed'
                  CHECK (status IN ('placed', 'paid', 'shipped', 'delivered', 'cancelled')),
    order_date    TIMESTAMPTZ NOT NULL DEFAULT now(),
    shipped_at    TIMESTAMPTZ,
    delivered_at  TIMESTAMPTZ
);

COMMENT ON TABLE  orders IS 'One row per customer order. Monetary value lives in order_items (an order total = SUM(quantity * unit_price) over its order_items); orders itself has no amount column.';
COMMENT ON COLUMN orders.status IS 'Lifecycle state, exactly one of: placed, paid, shipped, delivered, cancelled. "Completed" means delivered. Cancelled orders should be excluded from revenue.';
COMMENT ON COLUMN orders.order_date IS 'When the order was placed. Revenue by month groups on this column.';
COMMENT ON COLUMN orders.shipped_at IS 'NULL until the order ships. shipped_at - order_date is fulfilment latency.';

CREATE TABLE IF NOT EXISTS order_items (
    order_item_id SERIAL PRIMARY KEY,
    order_id      INTEGER NOT NULL REFERENCES orders(order_id) ON DELETE CASCADE,
    product_id    INTEGER NOT NULL REFERENCES products(product_id),
    quantity      INTEGER NOT NULL CHECK (quantity > 0),
    unit_price    NUMERIC(10, 2) NOT NULL CHECK (unit_price >= 0)
);

COMMENT ON TABLE  order_items IS 'Line items of an order: what was bought, how many, and the price AT SALE TIME (a historical snapshot of products.unit_price, which may differ from the current price).';
COMMENT ON COLUMN order_items.unit_price IS 'Price per unit when sold. Always use this (not products.unit_price) for historical revenue.';

CREATE TABLE IF NOT EXISTS payments (
    payment_id    SERIAL PRIMARY KEY,
    order_id      INTEGER NOT NULL REFERENCES orders(order_id) ON DELETE CASCADE,
    method        VARCHAR(20) NOT NULL CHECK (method IN ('card', 'paypal', 'bank_transfer', 'cash_on_delivery', 'gift_card')),
    amount        NUMERIC(12, 2) NOT NULL CHECK (amount >= 0),
    status        VARCHAR(20) NOT NULL DEFAULT 'pending'
                  CHECK (status IN ('pending', 'completed', 'failed', 'refunded')),
    paid_at       TIMESTAMPTZ
);

COMMENT ON TABLE  payments IS 'Payment attempts for orders. An order can have several payments (retries, partial refunds). Successful revenue = payments with status = ''completed''.';
COMMENT ON COLUMN payments.amount IS 'Payment amount in USD. SUM(amount) over completed payments is the cash actually collected.';

CREATE TABLE IF NOT EXISTS shipments (
    shipment_id   SERIAL PRIMARY KEY,
    order_id      INTEGER NOT NULL REFERENCES orders(order_id) ON DELETE CASCADE,
    carrier       VARCHAR(60) NOT NULL,
    tracking_no   VARCHAR(60) UNIQUE,
    shipped_at    TIMESTAMPTZ NOT NULL,
    delivered_at  TIMESTAMPTZ,
    shipping_cost NUMERIC(10, 2) NOT NULL DEFAULT 0
);

COMMENT ON TABLE  shipments IS 'Physical shipments. An order may ship in multiple parcels, so this is one-to-many from orders. delivered_at NULL means in transit.';
COMMENT ON COLUMN shipments.shipping_cost IS 'What we paid the carrier, in USD. This is a COST to the business, not revenue.';

CREATE TABLE IF NOT EXISTS reviews (
    review_id     SERIAL PRIMARY KEY,
    product_id    INTEGER NOT NULL REFERENCES products(product_id) ON DELETE CASCADE,
    customer_id   INTEGER NOT NULL REFERENCES customers(customer_id) ON DELETE CASCADE,
    rating        INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5),
    review_text   TEXT,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE  reviews IS 'Product reviews, 1 (worst) to 5 (best) stars. Verified purchasers only in real life; in this demo dataset any customer can review any product.';

-- ---------------------------------------------------------------------------
-- Indexes for the query patterns the eval questions exercise
-- ---------------------------------------------------------------------------

CREATE INDEX IF NOT EXISTS idx_orders_customer   ON orders(order_id, customer_id);
CREATE INDEX IF NOT EXISTS idx_orders_date       ON orders(order_date);
CREATE INDEX IF NOT EXISTS idx_order_items_order ON order_items(order_id);
CREATE INDEX IF NOT EXISTS idx_order_items_prod  ON order_items(product_id);
CREATE INDEX IF NOT EXISTS idx_payments_order    ON payments(order_id, status);
CREATE INDEX IF NOT EXISTS idx_reviews_product   ON reviews(product_id);
CREATE INDEX IF NOT EXISTS idx_addresses_cust    ON addresses(customer_id);

-- ---------------------------------------------------------------------------
-- Read-only role for the text-to-SQL agent  (run as the database owner)
-- ---------------------------------------------------------------------------
-- Why: the model generates SQL, users type natural language. Neither is a
-- trust boundary. This role IS one: it cannot modify anything, period.
-- We also set default_transaction_read_only as belt-and-braces; note Neon
-- restores this parameter per client connection even through PgBouncer.

DO $$
BEGIN
    IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'text2sql_ro') THEN
        CREATE ROLE text2sql_ro LOGIN PASSWORD 'Text2sql_ro!2026';
    END IF;
END
$$;

DO $$
BEGIN
    EXECUTE format('GRANT CONNECT ON DATABASE %I TO text2sql_ro', current_database());
END
$$;
GRANT USAGE ON SCHEMA public TO text2sql_ro;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO text2sql_ro;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT ON TABLES TO text2sql_ro;
ALTER ROLE text2sql_ro SET default_transaction_read_only = on;
ALTER ROLE text2sql_ro SET statement_timeout = '30s';
